class Solution:
    def partitionValue(self, nums: List[int]) -> int:
        nums.sort()
        return min(b - a for a, b in zip(nums, nums[1:]))

c.cpp:
class Solution {
public:
    int partitionValue(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int ans = INT_MAX;
        for (int i = 1; i < nums.size(); ++i) ans = min(ans, nums[i] - nums[i-1]);
        return ans;
    }
};

c.java:
class Solution {
    public int partitionValue(int[] nums) {
        Arrays.sort(nums);
        int ans = Integer.MAX_VALUE;
        for (int i = 1; i < nums.length; i++) ans = Math.min(ans, nums[i] - nums[i-1]);
        return ans;
    }
}

